```ts
const t0 = Date.now();
const end = t0 + 170000;
await bot.dismissBlockingUI();
// equip
for (const name of ['Bronze sword','Wooden shield']) {
  const it = sdk.findInventoryItem(new RegExp('^'+name+'$','i'));
  if (it) { try { await bot.equipItem(it); } catch(e){} }
}
const targets = [/^Rat$/i,/^Man$/i,/^Woman$/i,/^Imp$/i,/^Duck$/i,/^Giant spider$/i];
const killed = [];
const maxKills = 6;
while (Date.now() < end && killed.length < maxKills) {
  const st = sdk.getState();
  if (!st) { await sdk.waitForTicks(2); continue; }
  // pick nearest matching npc that is attackable and reachable
  const cand = st.nearbyNpcs
    .filter(n => targets.some(r=>r.test(n.name)))
    .filter(n => n.optionsWithIndex.some(o=>/attack/i.test(o.text)))
    .filter(n => !n.unreachable)
    .sort((a,b)=>a.distance-b.distance)[0];
  if (!cand) { 
    // wander / wait for spawn
    await sdk.waitForTicks(5); 
    continue; 
  }
  const name = cand.name;
  const opt = cand.optionsWithIndex.find(o=>/attack/i.test(o.text));
  try {
    await sdk.sendInteractNpc(cand.index, opt.opIndex);
  } catch(e){ await sdk.waitForTicks(2); continue; }
  // wait for combat start then end
  await sdk.waitForCondition(s=>s.player?.combat?.inCombat===true, 5000).catch(()=>{});
  const r = await sdk.waitForCondition(s=>!(s.player?.combat?.inCombat), 30000).catch(()=>null);
  // check if npc still nearby
  const st2 = sdk.getState();
  const still = st2?.nearbyNpcs.some(n=>n.name===name && n.distance<8);
  if (!still) { killed.push(name); console.log('KILLED', name); }
}
return killed;
```

