  const npc=s.nearbyNpcs.filter(n=>/^giant rat$/i.test(n.name)&&n.combatLevel>=6&&n.reachable!==false&&n.optionsWithIndex.some(o=>/attack/i.test(o.text))).sort((x,y)=>x.distance-y.distance)[0];
  if(!npc){ await sdk.waitForTicks(2); continue; }
  if(await attackNpc(npc)){ killed.push('Giant rat:'+npc.combatLevel); console.log('KILLED Giant rat',npc.combatLevel); break; }
}
const s=sdk.getState();
console.log('nearby',[...new Set((s?.nearbyNpcs||[]).filter(n=>/rat/i.test(n.name)).map(n=>n.name+':'+n.combatLevel))].join(','));
return {killed, hp:s?.player?.hp};
